import{_ as t,o as a,c as n,ag as s}from"./chunks/framework.CrXGS008.js";const u=JSON.parse('{"title":"Tunnels","description":"","frontmatter":{},"headers":[],"relativePath":"car-wash/tunnels.md","filePath":"car-wash/tunnels.md"}'),o={name:"car-wash/tunnels.md"};function r(i,e,l,h,d,c){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="tunnels" tabindex="-1">Tunnels <a class="header-anchor" href="#tunnels" aria-label="Permalink to &quot;Tunnels&quot;">​</a></h1><p>A tunnel is an entrance where the driver stops, a line the vehicle follows, and the arches, brushes and dryer along it. Two tunnels come ready to use: <strong>Strawberry</strong> and <strong>Little Seoul</strong>.</p><h2 id="how-a-wash-goes" tabindex="-1">How a wash goes <a class="header-anchor" href="#how-a-wash-goes" aria-label="Permalink to &quot;How a wash goes&quot;">​</a></h2><ol><li>The driver stops at the entrance, facing the exit. A prompt shows the lowest price.</li><li><strong>E</strong> opens the wash menu with the programs and their prices (job discounts and the tunnel percentage included).</li><li>The price is paid, then the vehicle is guided along the line: soap, brushes, rinse, dryer, depending on the program. Everyone nearby sees the same wash.</li><li>At the exit the vehicle is clean, and waxed if the program includes wax.</li></ol><p>The entrance refuses the wash when:</p><ul><li>the tunnel is already in use (one vehicle at a time);</li><li>the vehicle faces the wrong way;</li><li>another vehicle blocks the lane;</li><li>the vehicle class is blocked, or the vehicle is too wide (<code>BlockedClasses</code>, <code>MaxVehicleWidth</code>);</li><li>the vehicle is already clean and <code>RequireDirt</code> is on;</li><li>the player cannot pay.</li></ul><h2 id="the-tunnel-editor" tabindex="-1">The tunnel editor <a class="header-anchor" href="#the-tunnel-editor" aria-label="Permalink to &quot;The tunnel editor&quot;">​</a></h2><p>Open it with <code>/nay:carwash</code>, or with <strong>Manage tunnels</strong> on the Car Wash page of <code>/nay</code>. It needs the scope <code>nay_car_wash.config</code>.</p><p>The manager lists the tunnels: go to one, edit it, open or close it, delete it. To add one:</p><ol><li><p><strong>Create here</strong>: stand at the entrance, facing the exit. Or <strong>Copy</strong> one of the base game car washes.</p></li><li><p>Pick an element (entrance, line start and end, arches, brushes, dryer) and move it with the buttons or the keyboard:</p><ul><li>arrows: forward, back, left, right along the lane;</li><li>Page Up / Page Down: height;</li><li>Q / E: rotate;</li><li>Tab: next element.</li></ul><p>Three step sizes are available for fine adjustments.</p></li><li><p><strong>To my position</strong> and <strong>To ground</strong> snap the selected element. <strong>Walk around</strong> (G) frees the mouse so you can move and look. Press G again to get the panel back.</p></li><li><p><strong>Save tunnel</strong>. The tunnel is live for every player right away.</p></li></ol><p>The editor fills the <code>Tunnels</code> setting. Its fields are described on the <a href="/car-wash/settings#tunnels">Settings</a> page.</p>',11)])])}const g=t(o,[["render",r]]);export{u as __pageData,g as default};
